import React, { useEffect, useState } from "react";

export default function ReferralHistoryTable() {
  const [referrals, setReferrals] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    const fetchReferralHistory = async () => {
      setLoading(true);
      setError(null);

      const token = localStorage.getItem("authToken");
      const baseUrl = process.env.REACT_APP_API_BASE_URL?.trim() || "http://localhost:8080";

      try {
        const res = await fetch(`${baseUrl}/api/bonus-history/all-referrals`, {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        });

        if (!res.ok) throw new Error("Failed to fetch referral history");

        const data = await res.json();
        setReferrals(data);
      } catch (err) {
        console.error("Error fetching referrals:", err);
        setError(err.message || "Something went wrong");
      } finally {
        setLoading(false);
      }
    };

    fetchReferralHistory();
  }, []);

  return (
    <div className="p-6 bg-gray-50 rounded-lg shadow-md">
      <h2 className="text-2xl font-semibold mb-4 text-gray-800">Referral Bonus History</h2>

      {loading && (
        <div className="space-y-2">
          {[...Array(3)].map((_, i) => (
            <div key={i} className="h-8 bg-gray-200 rounded animate-pulse"></div>
          ))}
        </div>
      )}

      {error && <p className="text-red-500 text-center">{error}</p>}

      {!loading && !error && (
        <div className="overflow-x-auto">
          <table className="min-w-full bg-white rounded-lg shadow-md border border-gray-200">
            <thead className="bg-gray-100">
              <tr>
                {["Type", "Amount", "Referrer", "User", "Created At"].map((header) => (
                  <th key={header} className="px-4 py-3 text-left text-sm font-medium text-gray-700 border-b">
                    {header}
                  </th>
                ))}
              </tr>
            </thead>
            <tbody>
              {referrals.length > 0 ? (
                referrals.map((ref, index) => (
                  <tr key={index} className="hover:bg-gray-50 transition-colors">
                    <td className="px-4 py-2 border">{ref.type}</td>
                    <td className="px-4 py-2 border text-green-600 font-semibold">{ref.amount.toFixed(2)}</td>
                    <td className="px-4 py-2 border">{ref.sourceGameId}</td>
                    <td className="px-4 py-2 border">{ref.userGameId}</td>
                    <td className="px-4 py-2 border">
                      {new Date(ref.createdAt).toLocaleString("en-US", {
                        dateStyle: "medium",
                        timeStyle: "short",
                      })}
                    </td>
                  </tr>
                ))
              ) : (
                <tr>
                  <td colSpan="5" className="text-center py-4 text-gray-500">
                    No referral history found
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}
